/**
 * Computes a lightweight fingerprint of a route's current state.
 * Used to detect if the route has changed between recommendation generation
 * and dispatcher acceptance (stale-recommendation guard).
 * @param {object} route
 * @returns {string}
 */
function computeRouteVersionKey(route) {
  if (!route || !route.stops) return 'no-route';
  // Fingerprint = stop count + first-stop name + completed-stop count
  const completedCount = route.stops.filter(s => s.status === 'completed' || s.status === 'passed').length;
  const firstName = route.stops[0]?.name || '';
  return `${route.id}:stops=${route.stops.length}:completed=${completedCount}:first=${firstName}`;
}

