// Handle student cancellation and route recalculation
cancelStudent(studentId) {
  const student = this.state.students.find(s => s.id === studentId);
  if (!student) return;

  const prevBusId = student.busId;
  const prevRouteId = student.routeId;
  const prevStopName = student.stopName;

  // 1. Identify current bus and route & snapshot BEFORE (original) state
  const bus = (prevBusId && prevBusId !== 'UNASSIGNED')
    ? this.state.buses.find(b => b.id === prevBusId)
    : null;
  const route = (prevRouteId && prevRouteId !== 'UNASSIGNED')
    ? this.state.routes.find(r => r.id === prevRouteId)
    : null;

  const beforeBus = bus ? JSON.parse(JSON.stringify(bus)) : null;
  const beforeRoute = route ? JSON.parse(JSON.stringify(route)) : null;
  const beforeLoad = bus ? (bus.currentLoad || 0) : 0;
  const beforeCapacity = bus ? bus.capacity : 54;
  const beforeAvailableSeats = beforeCapacity - beforeLoad;

  const originalState = {
    student: {
      id: student.id,
      name: student.name,
      status: student.status,
      busId: student.busId,
      routeId: student.routeId,
      stopName: student.stopName
    },
    bus: bus ? {
      id: bus.id,
      currentLoad: beforeLoad,
      capacity: beforeCapacity,
      availableSeats: beforeAvailableSeats
    } : null,
    route: route ? {
      id: route.id,
      delayMinutes: route.delayMinutes || 0,
      totalStops: route.stops ? route.stops.length : 0
    } : null
  };

  // 2. Compute PROPOSED state without mutating live operational route/bus/student
  // (Live state is strictly preserved until Dispatcher approves the recommendation)
  const afterLoad = Math.max(0, beforeLoad - 1);
  const afterAvailableSeats = beforeCapacity - afterLoad;

  let timeSavedMins = 2.0;
  let bypassedStop = null;
  let proposedStops = null;

  if (route && route.stops) {
    proposedStops = JSON.parse(JSON.stringify(route.stops));
    const stopIndex = proposedStops.findIndex(st =>
      (st.name && prevStopName && st.name.toLowerCase().includes(prevStopName.toLowerCase())) ||
      (prevStopName && prevStopName.toLowerCase().includes(st.name.toLowerCase()))
    );
    if (stopIndex >= 0) {
      const pStop = proposedStops[stopIndex];
      pStop.studentsCount = Math.max(0, (pStop.studentsCount || 0) - 1);
      if (pStop.studentsCount === 0 && pStop.status !== 'completed' && pStop.status !== 'destination') {
        timeSavedMins = 3.5;
        bypassedStop = pStop.name;
      }
    }
  }

  const proposedState = {
    student: {
      id: student.id,
      name: student.name,
      status: 'absent_cancelled',
      busId: 'UNASSIGNED',
      routeId: 'UNASSIGNED',
      stopName: student.stopName
    },
    bus: bus ? {
      id: bus.id,
      currentLoad: afterLoad,
      capacity: beforeCapacity,
      availableSeats: afterAvailableSeats
    } : null,
    route: route ? {
      id: route.id,
      timeSavedMins,
      delayMinutes: Math.max(0, (route.delayMinutes || 0) - timeSavedMins),
      bypassedStop
    } : null
  };

  // Set indicator that cancellation is pending review, but keep original assignment intact
  student.cancellationPending = true;

  // 3. Store disruption with Before / Proposed route information
  const now = new Date();
  const timeStr = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
  const newId = `DIS-2026-00${this.state.disruptions.length + 1}`;
  const selectionReason = `Selected because the bus is already assigned to the route, has increased available capacity (${afterAvailableSeats} seats), and saves ${timeSavedMins} minutes by bypassing the stop.`;
  const planId = `REPLAN-CAN-${Math.floor(100 + Math.random() * 900)}`;

  const disruption = {
    id: newId,
    _createdAtMs: Date.now(),
    reportedAt: timeStr,
    type: 'student_cancel',
    title: `Student Absence & Cancellation – ${student.name}`,
    studentId: student.id,
    studentName: student.name,
    busId: prevBusId,
    routeId: prevRouteId,
    location: prevStopName || 'Scheduled Stop',
    severity: 'info',
    impact: `Passenger cancellation requested. Proposed: ${prevBusId} load (${beforeLoad} → ${afterLoad}). Awaiting dispatcher approval.`,
    status: 'unresolved',
    originalState,
    proposedState,
    beforeRoute,
    afterRoute: route ? { ...beforeRoute, proposedStops, proposedDelayMinutes: Math.max(0, (route.delayMinutes || 0) - timeSavedMins) } : null,
    beforeBus: {
      id: prevBusId,
      load: beforeLoad,
      capacity: beforeCapacity,
      availableSeats: beforeAvailableSeats
    },
    afterBus: {
      id: prevBusId,
      load: afterLoad,
      capacity: beforeCapacity,
      availableSeats: afterAvailableSeats
    },
    aiRecommendationAvailable: true,
    aiRecommendation: {
      planId,
      strategy: 'Schedule Dwell Compression & Capacity Release',
      recommendedBusId: prevBusId,
      recommendedRouteId: prevRouteId,
      availableSeats: `${afterAvailableSeats} seats available (${afterLoad}/${beforeCapacity} load)`,
      currentLocation: bus ? (route?.stops?.find(s => s.status === 'next')?.name || prevStopName || 'In Transit') : 'In Transit',
      driverAvailability: `${route?.assignedDriver || 'Assigned Driver'} (Active, No commitment conflicts)`,
      routeCompatibility: `Compatible (Assigned to ${prevRouteId})`,
      estimatedAdditionalDelay: `-${timeSavedMins} min (Ahead of schedule)`,
      selectionReason: selectionReason,
      estRecoveryTimeMins: 0,
      timeSavedMins: timeSavedMins,
      newEtaDifference: `-${timeSavedMins} min (Ahead of schedule)`,
      explanation: selectionReason,
      originalState,
      proposedState,
      candidateEvaluations: [
        {
          busId: prevBusId,
          routeId: prevRouteId,
          driverName: route?.assignedDriver || 'Assigned Driver',
          location: bus ? (route?.stops?.find(s => s.status === 'next')?.name || 'In Transit') : 'In Transit',
          seatsAvailable: afterAvailableSeats,
          delayMins: -timeSavedMins,
          isFeasible: true,
          statusText: 'Optimal Assigned Bus (Stop Bypassed)'
        },
        {
          busId: 'BUS-02',
          routeId: 'RT-102',
          driverName: 'David Chen',
          location: 'West Portal',
          seatsAvailable: 10,
          delayMins: 0,
          isFeasible: false,
          statusText: 'Driver already assigned to another route (RT-102)'
        },
        {
          busId: 'BUS-03',
          routeId: 'RT-103',
          driverName: 'Elena Rostova',
          location: 'Market St',
          seatsAvailable: 11,
          delayMins: 0,
          isFeasible: false,
          statusText: 'Driver already assigned to another route (RT-103)'
        }
      ],
      tradeoffs: [
        `Proposed: Free 1 seat on ${prevBusId} (${afterAvailableSeats} available seats)`,
        `Proposed: Save ~${timeSavedMins} mins dwell time along route`,
        `0 impact to remaining scheduled passengers`
      ]
    }
  };

  this.state.disruptions.unshift(disruption);
  this.state.selectedDisruptionId = newId;
  this.state.metrics.activeDisruptionsCount += 1;

  // Log recommendation generated in audit trail
  this.logRecommendationGenerated(newId, disruption.aiRecommendation, {
    originalState,
    proposedState,
    source: 'Student Cancellation Request'
  });

  // If offline / degraded, store change locally
  if (this.state.networkStatus !== 'online') {
    this.queueOfflineChange('CANCEL_STUDENT', `Cancellation requested for ${student.name} on ${prevRouteId}`, {
      studentId: student.id,
      prevBusId,
      prevRouteId,
      disruptionId: newId
    });
  }

  this.showToast(`Cancellation request for ${student.name} evaluated. Proposed dwell savings: ${timeSavedMins}m. Awaiting Dispatcher Approval.`, 'info');
  this.setActiveTab('replanning');
  this.notify();
}

