// Unified dispatcher action handler (online execution vs offline store-and-forward queueing)
dispatchAction(actionInput = {}) {
  const actionId = actionInput.actionId || `ACT-${Date.now()}-${Math.floor(Math.random() * 10000)}`;
  const userId = actionInput.userId || (this.state.currentUser ? this.state.currentUser.id : 'USR-DISPATCHER-01');
  const role = actionInput.role || (this.state.currentRole || 'dispatcher');
  const user = actionInput.user || (this.state.currentUser ? this.state.currentUser.name : 'Dispatcher');
  const actionType = actionInput.actionType || 'UNKNOWN_ACTION';
  const timestamp = actionInput.timestamp || new Date().toISOString();
  const payload = actionInput.payload || {};

  if (this.state.networkStatus === 'online') {
    // 1. Online action processed normally
    const actionItem = {
      actionId,
      id: actionId,
      timestamp,
      userId,
      role,
      'userId/role': `${userId}/${role}`,
      user,
      actionType,
      payload,
      status: 'EXECUTED',
      retryCount: 0,
      lastAttempt: timestamp,
      error: null,
      errorMessage: null
    };

    if (!this.state.syncedActionIds) {
      this.state.syncedActionIds = new Set();
    }
    this.state.syncedActionIds.add(actionId);

    this.state.metrics.recentAuditLogs.unshift({
      id: `LOG-ONLINE-${Date.now()}-${Math.floor(Math.random() * 100)}`,
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }),
      user: `${userId} (${role})`,
      event: `[ONLINE] ${actionType} (${actionId})`,
      status: 'EXECUTED'
    });

    this.showToast(`Action ${actionType} executed online.`, 'success');
    this.notify();
    return actionItem;
  } else {
    // 2. If network becomes unavailable, action is preserved locally
    return this.queueAction({
      actionId,
      userId,
      role,
      actionType,
      payload,
      description: actionInput.description
    });
  }
}

